import { useMemo, useState } from 'react';
import {
  Activity, ArrowDownLeft, ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight,
  BarChart3, Bell, Calendar, Check, ChevronDown, ChevronLeft, ChevronRight,
  CircleDollarSign, ClipboardList, CloudUpload, CookingPot, CreditCard, FileChartColumn,
  FileText, Filter, Grid2X2, HandCoins, Home, LayoutDashboard, ListFilter, LogOut,
  Menu, MoreHorizontal, Package, Plus, Search, Settings, ShoppingBasket, SlidersHorizontal,
  Store, Tags, Truck, Users, Wallet, X, Eye, Download, Trash2, Pencil, CheckCircle2,
  Receipt, CalendarDays, ChartNoAxesCombined, Clock3, Boxes, RotateCcw
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';

type Page = 'Home'|'Invoice'|'Sale'|'Vendor'|'More'|'Stock Sheet'|'Reports'|'Schedule'|'Settings'|'Sale Preview'|'Set Sale Priority'|'Set Vendor Priority'|'Estimation Sheet';
type Item = {name:string; code:string; category:string; opening:number; purchase:number; received:number; damaged:number; closing:number; sale:number; mrp:number; price:number; vendor:string; unit:string};
type SaleRow = {name:string; amount:number; kind:string; date:string};
type Invoice = {id:string; vendor:string; date:string; amount:number; status:string; file?:string};
const seedItems:Item[]=[
 {name:'PRAWNS (MEDIUM)',code:'SEA-001',category:'Seafood',opening:18,purchase:24,received:24,damaged:1,closing:17,sale:24,mrp:1080,price:920,vendor:'Coastal Catch',unit:'kg'},
 {name:'PRAWNS (LARGE)',code:'SEA-002',category:'Seafood',opening:12,purchase:18,received:18,damaged:0,closing:10,sale:20,mrp:1280,price:1100,vendor:'Coastal Catch',unit:'kg'},
 {name:'FRESH FISH',code:'SEA-003',category:'Seafood',opening:22,purchase:25,received:25,damaged:2,closing:21,sale:24,mrp:760,price:620,vendor:'Blue Bay Seafood',unit:'kg'},
 {name:'CHICKEN BONELESS',code:'MEA-001',category:'Meat',opening:16,purchase:20,received:20,damaged:0,closing:14,sale:22,mrp:480,price:395,vendor:'Farm Fresh Meats',unit:'kg'},
 {name:'MUTTON',code:'MEA-002',category:'Meat',opening:9,purchase:12,received:12,damaged:0,closing:8,sale:13,mrp:920,price:780,vendor:'Farm Fresh Meats',unit:'kg'},
 {name:'BASMATI RICE',code:'GRO-001',category:'Groceries',opening:42,purchase:30,received:30,damaged:0,closing:38,sale:34,mrp:115,price:88,vendor:'Sri Lakshmi Traders',unit:'kg'},
 {name:'COOKING OIL',code:'GRO-002',category:'Groceries',opening:24,purchase:18,received:18,damaged:0,closing:16,sale:26,mrp:185,price:148,vendor:'Sri Lakshmi Traders',unit:'L'},
 {name:'ONION',code:'VEG-001',category:'Vegetables',opening:35,purchase:25,received:25,damaged:1,closing:30,sale:29,mrp:58,price:42,vendor:'Nirmal Veg Market',unit:'kg'},
 {name:'TOMATO',code:'VEG-002',category:'Vegetables',opening:28,purchase:24,received:24,damaged:2,closing:21,sale:29,mrp:48,price:34,vendor:'Nirmal Veg Market',unit:'kg'},
 {name:'GREEN CHILLI',code:'VEG-003',category:'Vegetables',opening:8,purchase:10,received:10,damaged:0,closing:7,sale:11,mrp:90,price:64,vendor:'Nirmal Veg Market',unit:'kg'},
 {name:'TURMERIC POWDER',code:'SPI-001',category:'Spices',opening:5,purchase:4,received:4,damaged:0,closing:4,sale:5,mrp:340,price:275,vendor:'Sri Lakshmi Traders',unit:'kg'},
 {name:'GARAM MASALA',code:'SPI-002',category:'Spices',opening:4,purchase:3,received:3,damaged:0,closing:3,sale:4,mrp:520,price:420,vendor:'Sri Lakshmi Traders',unit:'kg'},
 {name:'GINGER GARLIC PASTE',code:'SPI-003',category:'Spices',opening:10,purchase:8,received:8,damaged:0,closing:7,sale:11,mrp:160,price:120,vendor:'Annapurna Foods',unit:'kg'},
 {name:'SODA / SOFT DRINKS',code:'BEV-001',category:'Beverages',opening:32,purchase:36,received:36,damaged:0,closing:24,sale:44,mrp:55,price:34,vendor:'Metro Beverages',unit:'pcs'},
 {name:'PACKAGING BOX',code:'SUP-001',category:'Supplies',opening:100,purchase:80,received:80,damaged:0,closing:52,sale:128,mrp:12,price:7,vendor:'PackRight Supplies',unit:'pcs'},
];
const seedSales:SaleRow[]=[
 {name:'Transport Charges',amount:425,kind:'Expense',date:'2026-10-17'}, {name:'Discount',amount:2520,kind:'Discount',date:'2026-10-17'},
 {name:'UPI / QR Pay',amount:12000,kind:'Payment',date:'2026-10-17'}, {name:'Invoice Pay',amount:204970,kind:'Invoice',date:'2026-10-17'},
 {name:'Stationery',amount:900,kind:'Expense',date:'2026-10-16'}, {name:'Tea & Refreshments',amount:450,kind:'Expense',date:'2026-10-16'},
];
const seedInvoices:Invoice[]=[
 {id:'INV-2026-1048',vendor:'Coastal Catch',date:'2026-10-17',amount:28400,status:'Paid'},
 {id:'INV-2026-1047',vendor:'Nirmal Veg Market',date:'2026-10-17',amount:8340,status:'Pending'},
 {id:'INV-2026-1046',vendor:'Sri Lakshmi Traders',date:'2026-10-16',amount:12500,status:'Paid'},
 {id:'INV-2026-1045',vendor:'Farm Fresh Meats',date:'2026-10-16',amount:19800,status:'Review'},
 {id:'INV-2026-1044',vendor:'Metro Beverages',date:'2026-10-15',amount:6450,status:'Paid'},
];
const seedVendors=['Coastal Catch','Blue Bay Seafood','Farm Fresh Meats','Sri Lakshmi Traders','Nirmal Veg Market','Annapurna Foods','Metro Beverages','PackRight Supplies'];
const navItems:{label:Page;icon:LucideIcon}[]=[{label:'Home',icon:Home},{label:'Invoice',icon:Receipt},{label:'Sale',icon:Tags},{label:'Vendor',icon:Store},{label:'More' as Page,icon:MoreHorizontal}];
const fmt=(n:number)=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(n);
const num=(n:number)=>new Intl.NumberFormat('en-IN').format(n);
const getStored=<T,>(key:string,fallback:T):T=>{try{const v=localStorage.getItem(key);return v?JSON.parse(v) as T:fallback}catch{return fallback}};
const today=()=>new Date().toISOString().slice(0,10);
function IconButton({icon:Icon,label,onClick}: {icon:LucideIcon;label:string;onClick?:()=>void}){return <button className="icon-button" aria-label={label} title={label} onClick={onClick}><Icon size={17}/></button>}
function App(){
 const [page,setPage]=useState<Page>('Home'); const [items,setItems]=useState<Item[]>(()=>getStored('prawns-items',seedItems));
 const [sales,setSales]=useState<SaleRow[]>(()=>getStored('prawns-sales',seedSales)); const [vendors,setVendors]=useState<string[]>(()=>getStored('prawns-vendors',seedVendors)); const [editingItem,setEditingItem]=useState<Item|null>(null); const [invoices,setInvoices]=useState<Invoice[]>(()=>getStored('prawns-invoices',seedInvoices));
 const [search,setSearch]=useState(''); const [filter,setFilter]=useState('All categories'); const [toast,setToast]=useState(''); const [modal,setModal]=useState<'sale'|'invoice'|'vendor'|'item'|null>(null); const [moreOpen,setMoreOpen]=useState(false); const [range,setRange]=useState('Today'); const [selectedDate,setSelectedDate]=useState(today()); const [report,setReport]=useState('Stock Status Report'); const [activeTab,setActiveTab]=useState('Stock Status Reports');
 const notify=(message:string)=>{setToast(message);setTimeout(()=>setToast(''),2800)};
 const saveItems=(n:Item[])=>{setItems(n);localStorage.setItem('prawns-items',JSON.stringify(n))};
 const saveSales=(n:SaleRow[])=>{setSales(n);localStorage.setItem('prawns-sales',JSON.stringify(n))};
 const saveInvoices=(n:Invoice[])=>{setInvoices(n);localStorage.setItem('prawns-invoices',JSON.stringify(n))};
 const go=(p:Page)=>{setPage(p);setMoreOpen(false);setSearch('')};
 const filteredItems=useMemo(()=>items.filter(i=>(filter==='All categories'||i.category===filter)&&(i.name.toLowerCase().includes(search.toLowerCase())||i.code.toLowerCase().includes(search.toLowerCase())||i.vendor.toLowerCase().includes(search.toLowerCase()))),[items,filter,search]);
 const totalStock=items.reduce((s,i)=>s+i.closing,0); const lowStock=items.filter(i=>i.closing<=Math.max(3,i.opening*.25)).length;
 const transactionSum=sales.filter(s=>s.date===selectedDate).reduce((s,x)=>s+x.amount,0);
 const summary=[{title:'Counter Cash',value:fmt(170047),tone:'yellow',icon:Wallet,sub:'+8.2% from yesterday'}, {title:'Invoice Amount',value:fmt(511310),tone:'purple',icon:FileText,sub:'12 invoices this week'}, {title:'Sale Amount',value:fmt(362750),tone:'lime',icon:ChartNoAxesCombined,sub:'+12.4% from yesterday'}, {title:'Expenditure',value:fmt(18745),tone:'cyan',icon:HandCoins,sub:'Across 8 expense items'}, {title:'Available Stock · MRP',value:fmt(803179),tone:'pink',icon:Boxes,sub:`${num(totalStock)} units on hand`}, {title:'Available Stock · Invoice',value:fmt(693244),tone:'teal',icon:Package,sub:`${lowStock} items running low`}];
 const openReport=(name:string)=>{setReport(name);go('Reports')};
 const addSale=(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const row:SaleRow={name:String(f.get('name')),amount:Number(f.get('amount')),kind:String(f.get('kind')),date:String(f.get('date'))};saveSales([row,...sales]);setModal(null);notify('Transaction saved to the daily ledger.')};
 const addInvoice=(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const file=f.get('file') as File;const row:Invoice={id:`INV-${new Date().getFullYear()}-${1049+invoices.length}`,vendor:String(f.get('vendor')),date:String(f.get('date')),amount:Number(f.get('amount')),status:'Pending',file:file?.name};saveInvoices([row,...invoices]);setModal(null);notify('Invoice uploaded and added to your ledger.')};
 const addItem=(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const row:Item={name:String(f.get('name')).toUpperCase(),code:String(f.get('code')||editingItem?.code||`NEW-${items.length+1}`),category:String(f.get('category')),opening:Number(f.get('opening')),purchase:editingItem?.purchase||0,received:editingItem?.received||0,damaged:editingItem?.damaged||0,closing:editingItem?.closing??Number(f.get('opening')),sale:editingItem?.sale||0,mrp:Number(f.get('mrp')),price:Number(f.get('price')),vendor:String(f.get('vendor')),unit:String(f.get('unit'))};if(editingItem){saveItems(items.map(i=>i.code===editingItem.code?row:i));notify('Stock item updated.')}else{saveItems([row,...items]);notify('Stock item added.')}setEditingItem(null);setModal(null)};
 const addVendor=(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const name=String(f.get('name'));const next=[name,...vendors];setVendors(next);localStorage.setItem('prawns-vendors',JSON.stringify(next));setModal(null);notify(`${name} added to your supplier list.`)};
 const title=page==='Home'?'Overview':page==='Stock Sheet'?'Stock Management':page;
 return <div className="app-shell">
  <aside className="sidebar">
   <button className="brand" onClick={()=>go('Home')}><span className="brand-mark"><CookingPot size={21}/></span><span className="brand-copy"><b>Nirooi</b><small>ADELLI POCHAMMA WINES · NIRMAL</small></span></button>
   <div className="side-label">WORKSPACE</div><nav className="side-nav">{navItems.slice(0,4).map(({label,icon:Icon})=><button key={label} onClick={()=>go(label)} className={`side-link ${page===label?'selected':''}`}><Icon size={17}/><span>{label==='Home'?'Dashboard':label==='Sale'?'Sales':label==='Vendor'?'Vendors':label}</span>{label==='Invoice'&&<em>{invoices.filter(i=>i.status==='Pending').length}</em>}</button>)}
    <button className={`side-link ${['Stock Sheet','Estimation Sheet'].includes(page)?'selected':''}`} onClick={()=>go('Stock Sheet')}><Grid2X2 size={17}/><span>Stock sheet</span></button>
   </nav>
   <div className="side-label more-label">MANAGE</div><nav className="side-nav">{[{label:'Reports' as Page,icon:BarChart3},{label:'Schedule' as Page,icon:CalendarDays},{label:'Set Sale Priority' as Page,icon:SlidersHorizontal},{label:'Settings' as Page,icon:Settings}].map(({label,icon:Icon})=><button key={label} className={`side-link ${page===label?'selected':''}`} onClick={()=>go(label)}><Icon size={17}/><span>{label==='Set Sale Priority'?'Priorities':label}</span></button>)}<button className={`side-link ${page==='More'?'selected':''}`} onClick={()=>go('More')}><MoreHorizontal size={17}/><span>More tools</span></button></nav>
   <div className="sidebar-spacer"/><div className="sidebar-card"><span className="online-dot"/><div><b>Today's ledger</b><small>Everything is up to date</small></div><CheckCircle2 size={17}/></div>
   <button className="profile" onClick={()=>go('Settings')}><span className="avatar">NA</span><span><b>Nirooi Adelli</b><small>Administrator</small></span><MoreHorizontal size={18}/></button>
  </aside>
  <main className="main-area">
   <header className="topbar"><div className="mobile-brand"><span className="brand-mark"><CookingPot size={18}/></span><b>Nirooi</b></div><div className="crumb"><span>Workspace</span><ChevronRight size={14}/><b>{title}</b></div><div className="top-actions"><div className="live-pill"><span/> Live sync</div><button className="top-icon" title="Search" onClick={()=>document.getElementById('global-search')?.focus()}><Search size={18}/></button><button className="top-icon notification" title="Notifications" onClick={()=>notify('You are all caught up.')}><Bell size={18}/><i/></button><div className="top-avatar">NA</div></div></header>
   <div className="content-wrap">
    {page==='Home'&&<>
     <div className="page-heading"><div><div className="eyebrow">SATURDAY, OCTOBER 17, 2026 <span className="eyebrow-dot"/> NIRMAL, TELANGANA</div><h1>Good morning, Nirooi <span>✦</span></h1><p>Here’s how your restaurant is doing today.</p></div><div className="heading-actions"><button className="button secondary" onClick={()=>go('Stock Sheet')}><Grid2X2 size={16}/> Stock sheet</button><button className="button primary" onClick={()=>setModal('sale')}><Plus size={16}/> New transaction</button></div></div>
     <div className="filter-row"><div className="segmented">{['Today','Week','Month'].map(x=><button key={x} className={range===x?'on':''} onClick={()=>setRange(x)}>{x}</button>)}</div><button className="date-pill" onClick={()=>{const d=prompt('Choose a date (YYYY-MM-DD)',selectedDate);if(d&&/^\d{4}-\d\d-\d\d$/.test(d))setSelectedDate(d)}}><Calendar size={15}/>{range==='Today'?'Oct 17, 2026':range==='Week'?'Oct 11 – 17, 2026':'October 2026'}<ChevronDown size={14}/></button><span className="filter-spacer"/><button className="quiet-button" onClick={()=>notify('Dashboard refreshed.') }><RotateCcw size={14}/> Refresh</button></div>
     <section className="summary-grid">{summary.map(({title,value,tone,icon:Icon,sub})=><article className={`summary-card ${tone}`} key={title}><div className="summary-top"><span>{title}</span><span className="summary-icon"><Icon size={16}/></span></div><div className="summary-value">{value}</div><div className="summary-sub">{sub.startsWith('+')?<ArrowUpRight size={13}/>:<span className="sub-bullet"/>}{sub}</div></article>)}</section>
     <section className="dashboard-grid"><article className="panel sales-panel"><div className="panel-head"><div><h2>Sales overview</h2><p>Revenue performance across your business</p></div><button className="select-button" onClick={()=>setRange(range==='Week'?'Month':'Week')}>{range}<ChevronDown size={14}/></button></div><div className="chart-legend"><span><i className="legend-bar"/> Revenue</span><span><i className="legend-line"/> Expenses</span><b>{fmt(362750)} <small>total sales</small></b></div><div className="chart"><div className="chart-y"><span>₹4L</span><span>₹3L</span><span>₹2L</span><span>₹1L</span><span>₹0</span></div><div className="chart-plot"><div className="chart-gridlines"><i/><i/><i/><i/><i/></div><svg viewBox="0 0 720 190" preserveAspectRatio="none" className="chart-svg"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#133293" stopOpacity=".2"/><stop offset="1" stopColor="#133293" stopOpacity="0"/></linearGradient></defs><path d="M0 149 C40 130 55 154 92 125 S143 112 180 132 S242 84 278 94 S326 120 365 82 S416 95 455 59 S510 75 548 52 S608 90 644 33 S690 68 720 22 V190 H0Z" fill="url(#fill)"/><path d="M0 149 C40 130 55 154 92 125 S143 112 180 132 S242 84 278 94 S326 120 365 82 S416 95 455 59 S510 75 548 52 S608 90 644 33 S690 68 720 22" fill="none" stroke="#133293" strokeWidth="3" vectorEffect="non-scaling-stroke" strokeLinecap="round"/><path d="M0 174 C55 165 62 172 92 161 S144 166 180 160 S242 150 278 158 S328 151 365 147 S416 154 455 142 S510 146 548 134 S607 139 644 129 S690 138 720 122" fill="none" stroke="#98a9dc" strokeWidth="2" strokeDasharray="4 5" vectorEffect="non-scaling-stroke" strokeLinecap="round"/></svg><div className="chart-x">{(range==='Today'?['9 AM','10 AM','11 AM','12 PM','1 PM','2 PM','3 PM','4 PM']:range==='Week'?['Mon','Tue','Wed','Thu','Fri','Sat','Sun']:['1 Oct','5 Oct','9 Oct','13 Oct','17 Oct','21 Oct','25 Oct','31 Oct']).map(x=><span key={x}>{x}</span>)}</div></div></div></article>
      <article className="panel stock-panel"><div className="panel-head"><div><h2>Stock health</h2><p>Inventory at a glance</p></div><button className="dots" onClick={()=>go('Stock Sheet')}><MoreHorizontal size={18}/></button></div><div className="stock-total"><span className="stock-total-icon"><Boxes size={17}/></span><div><small>Total stock value</small><strong>{fmt(803179)}</strong></div><span className="trend"><ArrowUpRight size={13}/> 6.8%</span></div><div className="donut-wrap"><div className="donut"><div><b>{items.length}</b><small>products</small></div></div><div className="stock-legend">{[['Seafood',18,'#133293'],['Groceries',25,'#4962a7'],['Meat',19,'#6d82c4'],['Vegetables',15,'#8fa2d7'],['Other',23,'#dbe2f3']].map(([label,n,color])=><div key={String(label)}><span><i style={{background:String(color)}}/>{label}</span><b>{n}%</b></div>)}</div></div><button className="panel-link" onClick={()=>go('Stock Sheet')}>View inventory <ArrowRight size={14}/></button></article>
     </section>
     <section className="dashboard-bottom"><article className="panel recent-panel"><div className="panel-head"><div><h2>Recent transactions</h2><p>Latest activity from your daily ledger</p></div><button className="text-link" onClick={()=>go('Sale')}>View all <ArrowRight size={14}/></button></div><TransactionList rows={sales.slice(0,5)} compact/></article><article className="panel low-panel"><div className="panel-head"><div><h2>Needs attention</h2><p>Items to restock soon</p></div><span className="count-badge">{lowStock} items</span></div><div className="low-list">{items.filter(i=>i.closing<=Math.max(3,i.opening*.25)).slice(0,4).map(i=><div className="low-row" key={i.code}><span className="low-icon"><Package size={15}/></span><div><b>{i.name}</b><small>{i.category} · {i.code}</small></div><div className="stock-meter"><span style={{width:`${Math.min(100,i.closing/i.opening*100)}%`}}/></div><span className="stock-qty">{i.closing} {i.unit}</span></div>)}</div><button className="panel-link" onClick={()=>go('Stock Sheet')}>Review stock <ArrowRight size={14}/></button></article></section>
    </>}
    {page==='Stock Sheet'&&<><div className="page-heading"><div><div className="eyebrow">INVENTORY MANAGEMENT <span className="eyebrow-dot"/> {num(items.length)} ITEMS</div><h1>Stock sheet</h1><p>Track opening balance, purchases, sales, and closing stock.</p></div><div className="heading-actions"><button className="button secondary" onClick={()=>{const csv=['Name,Code,Category,Opening,Purchase,Received,Damaged,Closing,Sale,MRP,Price,Vendor',...items.map(i=>[i.name,i.code,i.category,i.opening,i.purchase,i.received,i.damaged,i.closing,i.sale,i.mrp,i.price,i.vendor].join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='prawns-stock-sheet.csv';a.click();URL.revokeObjectURL(a.href);notify('Stock sheet exported as CSV.')}}><Download size={16}/> Export</button><button className="button primary" onClick={()=>{setEditingItem(null);setModal('item')}}><Plus size={16}/> Add item</button></div></div><div className="stock-kpis"><div><span className="kpi-icon orange"><Boxes size={17}/></span><small>Total products</small><b>{num(items.length)}</b></div><div><span className="kpi-icon green"><Check size={17}/></span><small>In stock</small><b>{num(items.filter(i=>i.closing>0).length)}</b></div><div><span className="kpi-icon red"><Activity size={17}/></span><small>Low stock</small><b>{num(lowStock)}</b></div><div><span className="kpi-icon violet"><CircleDollarSign size={17}/></span><small>Inventory value</small><b>{fmt(items.reduce((s,i)=>s+i.closing*i.price,0))}</b></div></div><div className="panel table-panel"><div className="table-toolbar"><div className="search-box"><Search size={16}/><input id="global-search" placeholder="Search items, code, or vendor…" value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button onClick={()=>setSearch('')}><X size={14}/></button>}</div><label className="filter-select"><ListFilter size={15}/><select value={filter} onChange={e=>setFilter(e.target.value)}><option>All categories</option>{[...new Set(items.map(i=>i.category))].map(c=><option key={c}>{c}</option>)}</select><ChevronDown size={13}/></label><span className="table-count">Showing {filteredItems.length} of {items.length} items</span></div><StockTable items={filteredItems} onUpdate={(code,field,value)=>saveItems(items.map(i=>i.code===code?{...i,[field]:Number(value),...(field==='sale'?{closing:Math.max(0,i.opening+i.received-Number(value)-i.damaged)}:{})}:i))} onEdit={i=>{setEditingItem(i);setModal('item')}}/><div className="table-footer"><span>Showing <b>{filteredItems.length?1:0}–{filteredItems.length}</b> of <b>{items.length}</b> products</span><div><button disabled><ChevronLeft size={15}/></button><button className="pg-active">1</button><button disabled><ChevronRight size={15}/></button></div></div></div><div className="table-note"><span><i className="note-dot green-dot"/> Healthy stock</span><span><i className="note-dot amber-dot"/> Running low (below 25%)</span><span><i className="note-dot red-dot"/> Needs reorder</span><span className="note-tip">Tip: click a stock quantity to update it inline.</span></div></>}
    {page==='Invoice'&&<InvoicePage invoices={invoices} search={search} setSearch={setSearch} setModal={setModal} onStatus={(id,status)=>saveInvoices(invoices.map(x=>x.id===id?{...x,status}:x))} notify={notify}/>}
    {page==='Sale'&&<SalesPage sales={sales} selectedDate={selectedDate} setSelectedDate={setSelectedDate} setModal={setModal} notify={notify}/>}
    {page==='Vendor'&&<VendorPage vendors={vendors} search={search} setSearch={setSearch} onAdd={()=>setModal('vendor')} onNotify={notify}/>}
    {page==='Reports'&&<ReportsPage report={report} setReport={setReport} selectedDate={selectedDate} onDate={()=>{const d=prompt('Choose a date (YYYY-MM-DD)',selectedDate);if(d)setSelectedDate(d)}} rows={sales} items={items} activeTab={activeTab} setActiveTab={setActiveTab} notify={notify}/>}
    {page==='Schedule'&&<SchedulePage notify={notify}/>}
    {page==='Set Sale Priority'&&<PriorityPage title="Sale priority" icon={ChartNoAxesCombined} names={['Prawns (Medium)','Fresh fish','Chicken boneless','Basmati rice','Mutton']} notify={notify}/>}
    {page==='Set Vendor Priority'&&<PriorityPage title="Vendor priority" icon={Truck} names={vendors} notify={notify}/>}
    {page==='Estimation Sheet'&&<EstimatePage items={items} notify={notify}/>}
    {page==='Sale Preview'&&<SalePreview sales={sales} selectedDate={selectedDate} setSelectedDate={setSelectedDate} go={go}/>}
    {page==='Settings'&&<SettingsPage notify={notify} items={items} sales={sales} invoices={invoices}/>}
    {page==='More'&&<MorePage go={go}/>}
   </div>
   <nav className="mobile-nav">{navItems.map(({label,icon:Icon})=><button key={label} className={(page===label||label==='More'&&['Reports','Schedule','Settings','Stock Sheet','Set Sale Priority','Set Vendor Priority','Estimation Sheet','Sale Preview'].includes(page))?'active':''} onClick={()=>label==='More'?setMoreOpen(!moreOpen):go(label)}><Icon size={19}/><span>{label}</span></button>)}</nav>
   {moreOpen&&<div className="mobile-more"><div className="more-handle"/><b>More tools</b>{(['Stock Sheet','Sale Preview','Set Sale Priority','Set Vendor Priority','Estimation Sheet','Reports','Schedule','Settings'] as Page[]).map(x=><button key={x} onClick={()=>go(x)}>{x}<ChevronRight size={15}/></button>)}</div>}
  </main>
  {toast&&<div className="toast"><CheckCircle2 size={17}/>{toast}<button onClick={()=>setToast('')}><X size={14}/></button></div>}
  {modal&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setModal(null)}}><div className="modal"><div className="modal-head"><div><h2>{modal==='sale'?'Add transaction':modal==='invoice'?'Upload invoice':modal==='vendor'?'Add vendor':editingItem?'Edit stock item':'Add stock item'}</h2><p>{modal==='sale'?'Record a sale, payment, or daily expense.':modal==='invoice'?'Add an invoice to your purchase ledger.':modal==='vendor'?'Create a supplier profile.':editingItem?'Update this product and its supplier details.':'Add a product to your stock sheet.'}</p></div><button onClick={()=>setModal(null)}><X size={18}/></button></div>{modal==='sale'&&<form onSubmit={addSale}><div className="form-grid"><label className="full">Description<input name="name" placeholder="e.g. Counter sale" required/></label><label>Type<select name="kind"><option>Sale</option><option>Expense</option><option>Discount</option><option>Payment</option><option>Invoice</option></select></label><label>Amount (₹)<input name="amount" type="number" min="1" step="0.01" required placeholder="0.00"/></label><label>Date<input name="date" type="date" defaultValue={today()} required/></label><label>Payment method<select name="method"><option>Cash</option><option>UPI / QR</option><option>Card</option><option>Credit</option></select></label></div><div className="modal-actions"><button type="button" className="button secondary" onClick={()=>setModal(null)}>Cancel</button><button className="button primary">Save transaction <ArrowRight size={15}/></button></div></form>}{modal==='invoice'&&<form onSubmit={addInvoice}><div className="form-grid"><label className="full">Vendor<select name="vendor" required>{vendors.map(v=><option key={v}>{v}</option>)}</select></label><label>Invoice date<input name="date" type="date" defaultValue={today()} required/></label><label>Amount (₹)<input name="amount" type="number" min="1" step="0.01" required placeholder="0.00"/></label><label className="upload-zone full"><CloudUpload size={24}/><b>Attach invoice PDF or image</b><small>PDF, JPG, or PNG · up to 10 MB</small><input name="file" type="file" accept=".pdf,image/*"/></label></div><div className="modal-actions"><button type="button" className="button secondary" onClick={()=>setModal(null)}>Cancel</button><button className="button primary">Add invoice <ArrowRight size={15}/></button></div></form>}{modal==='item'&&<form onSubmit={addItem}><div className="form-grid"><label className="full">Product name<input name="name" defaultValue={editingItem?.name||''} placeholder="e.g. Fresh prawns" required/></label><label>Category<select name="category" defaultValue={editingItem?.category||'Seafood'}><option>Seafood</option><option>Meat</option><option>Groceries</option><option>Vegetables</option><option>Spices</option><option>Beverages</option><option>Supplies</option></select></label><label>Vendor<select name="vendor" defaultValue={editingItem?.vendor||vendors[0]}>{vendors.map(v=><option key={v}>{v}</option>)}</select></label><label>Opening quantity<input name="opening" type="number" min="0" defaultValue={editingItem?.opening??0} required/></label><label>Unit<select name="unit" defaultValue={editingItem?.unit||'kg'}><option>kg</option><option>L</option><option>pcs</option><option>box</option></select></label><label>Invoice price (₹)<input name="price" type="number" min="0" defaultValue={editingItem?.price??0} required/></label><label>MRP (₹)<input name="mrp" type="number" min="0" defaultValue={editingItem?.mrp??0} required/></label></div><div className="modal-actions"><button type="button" className="button secondary" onClick={()=>{setEditingItem(null);setModal(null)}}>Cancel</button><button className="button primary">{editingItem?'Save item':'Add to stock sheet'} <ArrowRight size={15}/></button></div></form>}{modal==='vendor'&&<form onSubmit={addVendor}><div className="form-grid"><label className="full">Vendor name<input name="name" required placeholder="Business or supplier name"/></label><label>Contact person<input placeholder="Name"/></label><label>Phone<input placeholder="+91 00000 00000" type="tel"/></label><label className="full">Email<input placeholder="vendor@example.com" type="email"/></label><label className="full">Category<select><option>Seafood</option><option>Meat</option><option>Groceries</option><option>Vegetables</option><option>Other</option></select></label></div><div className="modal-actions"><button type="button" className="button secondary" onClick={()=>setModal(null)}>Cancel</button><button className="button primary">Save vendor <ArrowRight size={15}/></button></div></form>}</div></div>}
 </div>
}
function StockTable({items,onUpdate,onEdit}:{items:Item[];onUpdate:(code:string,field:keyof Item,value:string)=>void;onEdit:(item:Item)=>void}){return <div className="table-scroll"><table className="stock-table"><thead><tr><th rowSpan={2} className="item-head">Product / item</th><th colSpan={2} className="group opening-group">Opening</th><th colSpan={3} className="group receipt-group">Receipts &amp; adjustments</th><th colSpan={2} className="group sale-group">Sales</th><th colSpan={2} className="group value-group">Value</th><th rowSpan={2}>Supplier</th><th rowSpan={2}></th></tr><tr><th>Qty</th><th>Unit</th><th>Purchased</th><th>Received</th><th>Damaged</th><th>Sold</th><th>Closing</th><th>MRP</th><th>Cost</th></tr></thead><tbody>{items.map((i,index)=><tr key={i.code}><td className="item-cell"><span className={`category-mark color-${index%6}`}/><span><b>{i.name}</b><small>{i.code} <i>·</i> {i.category}</small></span></td><td><InlineNumber value={i.opening} onSave={v=>onUpdate(i.code,'opening',v)}/></td><td className="unit-cell">{i.unit}</td><td><InlineNumber value={i.purchase} onSave={v=>onUpdate(i.code,'purchase',v)}/></td><td><span className="received-number">{i.received}</span></td><td><InlineNumber value={i.damaged} onSave={v=>onUpdate(i.code,'damaged',v)}/></td><td><InlineNumber value={i.sale} onSave={v=>onUpdate(i.code,'sale',v)}/></td><td><span className={`closing-chip ${i.closing<=2?'danger':i.closing<=5?'warning':''}`}>{i.closing}</span></td><td className="money-cell">{num(i.mrp)}</td><td className="money-cell">{num(i.price)}</td><td className="vendor-cell">{i.vendor}</td><td><IconButton icon={Pencil} label="Edit item" onClick={()=>onEdit(i)}/></td></tr>)}</tbody></table>{items.length===0&&<div className="empty-state"><Search size={25}/><b>No matching products</b><span>Try another product name or category filter.</span></div>}</div>}
function InlineNumber({value,onSave}:{value:number;onSave:(v:string)=>void}){const [editing,setEditing]=useState(false);const [draft,setDraft]=useState(String(value));return editing?<input className="inline-input" type="number" value={draft} autoFocus onChange={e=>setDraft(e.target.value)} onBlur={()=>{onSave(draft);setEditing(false)}} onKeyDown={e=>{if(e.key==='Enter'){onSave(draft);setEditing(false)}if(e.key==='Escape')setEditing(false)}}/>:<button className="inline-number" onClick={()=>{setDraft(String(value));setEditing(true)}}>{value}</button>}
function TransactionList({rows,compact=false}:{rows:SaleRow[];compact?:boolean}){return <div className="transactions">{rows.map((r,i)=><div className="transaction-row" key={`${r.name}-${r.date}-${i}`}><span className={`transaction-icon ${r.kind.toLowerCase()==='expense'?'expense':r.kind.toLowerCase()==='sale'?'sale':r.kind.toLowerCase()==='payment'?'payment':'other'}`}>{r.kind==='Expense'?<ArrowDownLeft size={15}/>:r.kind==='Sale'?<ShoppingBasket size={15}/>:r.kind==='Payment'?<CreditCard size={15}/>:<Receipt size={15}/>}</span><div className="transaction-info"><b>{r.name}</b><small>{new Date(`${r.date}T00:00:00`).toLocaleDateString('en-IN',{day:'numeric',month:'short'})} · {r.kind}</small></div><strong className={r.kind==='Expense'?'negative':''}>{r.kind==='Expense'?'-':''}{fmt(r.amount)}</strong>{!compact&&<span className="status-pill paid">Recorded</span>}</div>)}</div>}
function InvoicePage({invoices,search,setSearch,setModal,onStatus,notify}:{invoices:Invoice[];search:string;setSearch:(s:string)=>void;setModal:(x:'sale'|'invoice'|'vendor'|'item'|null)=>void;onStatus:(id:string,status:string)=>void;notify:(s:string)=>void}){const [status,setStatus]=useState('All invoices');const visible=invoices.filter(i=>(status==='All invoices'||i.status===status)&&`${i.id} ${i.vendor}`.toLowerCase().includes(search.toLowerCase()));return <><div className="page-heading"><div><div className="eyebrow">PURCHASES <span className="eyebrow-dot"/> INVOICE LEDGER</div><h1>Invoices</h1><p>Keep every supplier invoice organized and up to date.</p></div><button className="button primary" onClick={()=>setModal('invoice')}><CloudUpload size={16}/> Upload invoice</button></div><div className="invoice-summary"><div><span className="invoice-sum-icon orange"><FileText size={18}/></span><small>Total this month</small><b>{fmt(invoices.reduce((a,i)=>a+i.amount,0))}</b><em>{invoices.length} invoices</em></div><div><span className="invoice-sum-icon green"><Check size={18}/></span><small>Paid</small><b>{fmt(invoices.filter(i=>i.status==='Paid').reduce((a,i)=>a+i.amount,0))}</b><em>{invoices.filter(i=>i.status==='Paid').length} invoices settled</em></div><div><span className="invoice-sum-icon amber"><Clock3 size={18}/></span><small>Pending review</small><b>{fmt(invoices.filter(i=>i.status!=='Paid').reduce((a,i)=>a+i.amount,0))}</b><em>{invoices.filter(i=>i.status!=='Paid').length} to review</em></div></div><div className="panel table-panel"><div className="table-toolbar"><div className="search-box"><Search size={16}/><input placeholder="Search invoice or vendor…" value={search} onChange={e=>setSearch(e.target.value)}/></div><label className="filter-select"><Filter size={15}/><select value={status} onChange={e=>setStatus(e.target.value)}><option>All invoices</option><option>Pending</option><option>Review</option><option>Paid</option></select><ChevronDown size={13}/></label><span className="table-count">{visible.length} invoices</span></div><div className="table-scroll"><table className="data-table"><thead><tr><th>Invoice #</th><th>Supplier</th><th>Date</th><th>Amount</th><th>Status</th><th>Attachment</th><th></th></tr></thead><tbody>{visible.map(i=><tr key={i.id}><td><b className="invoice-id">{i.id}</b></td><td><span className="table-primary">{i.vendor}</span><small className="table-secondary">Supplier invoice</small></td><td>{new Date(`${i.date}T00:00:00`).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}</td><td className="money-strong">{fmt(i.amount)}</td><td><span className={`status-pill ${i.status.toLowerCase()}`}>{i.status==='Paid'?<Check size={12}/>:<Clock3 size={12}/>} {i.status}</span></td><td>{i.file?<span className="file-chip"><FileText size={13}/>{i.file}</span>:<span className="muted">—</span>}</td><td><div className="row-actions"><IconButton icon={Eye} label="View invoice" onClick={()=>notify(`${i.id} · ${i.vendor} · ${fmt(i.amount)}`)}/><button className="dots" onClick={()=>onStatus(i.id,i.status==='Paid'?'Pending':'Paid')} title="Toggle payment status"><MoreHorizontal size={16}/></button></div></td></tr>)}</tbody></table>{visible.length===0&&<div className="empty-state">No invoices match your search.</div>}</div><div className="table-footer"><span>Showing <b>{visible.length}</b> of <b>{invoices.length}</b> invoices</span><div><button disabled><ChevronLeft size={15}/></button><button className="pg-active">1</button><button disabled><ChevronRight size={15}/></button></div></div></div></>}
function SalesPage({sales,selectedDate,setSelectedDate,setModal,notify}:{sales:SaleRow[];selectedDate:string;setSelectedDate:(s:string)=>void;setModal:(x:'sale'|'invoice'|'vendor'|'item'|null)=>void;notify:(s:string)=>void}){const daily=sales.filter(x=>x.date===selectedDate);const income=daily.filter(x=>x.kind==='Sale'||x.kind==='Payment').reduce((a,x)=>a+x.amount,0);const expenses=daily.filter(x=>x.kind==='Expense').reduce((a,x)=>a+x.amount,0);return <><div className="page-heading"><div><div className="eyebrow">DAILY LEDGER <span className="eyebrow-dot"/> SALES &amp; EXPENSES</div><h1>Sales</h1><p>Review today’s revenue, payments, and operating costs.</p></div><div className="heading-actions"><button className="button secondary" onClick={()=>notify('Sale summary exported as CSV.') }><Download size={16}/> Export</button><button className="button primary" onClick={()=>setModal('sale')}><Plus size={16}/> Add transaction</button></div></div><div className="filter-row"><button className="date-pill" onClick={()=>{const d=prompt('Choose a date (YYYY-MM-DD)',selectedDate);if(d)setSelectedDate(d)}}><Calendar size={15}/>{selectedDate}<ChevronDown size={14}/></button><span className="muted">Daily activity and transaction summary</span></div><div className="sale-kpi-grid"><div className="sale-kpi income"><span><ArrowDownLeft size={16}/></span><small>Total received</small><b>{fmt(income||362750)}</b><em>Cash, UPI, and card</em></div><div className="sale-kpi spent"><span><ArrowUpRight size={16}/></span><small>Total expenses</small><b>{fmt(expenses||18745)}</b><em>{daily.filter(x=>x.kind==='Expense').length||8} operating entries</em></div><div className="sale-kpi net"><span><Wallet size={16}/></span><small>Net cash position</small><b>{fmt((income||362750)-(expenses||18745))}</b><em>After recorded expenses</em></div></div><div className="two-column"><div className="panel"><div className="panel-head"><div><h2>Transaction details</h2><p>{daily.length} entries recorded for {selectedDate}</p></div><button className="text-link" onClick={()=>goSalePreview(setSelectedDate,notify)}>Daily summary <ArrowRight size={14}/></button></div><TransactionList rows={daily.length?daily:sales.slice(0,4)}/></div><div className="panel breakdown-panel"><div className="panel-head"><div><h2>Payment breakdown</h2><p>By method · today</p></div></div><div className="payment-bars"><div><span>Cash</span><b>₹170,047</b><div><i style={{width:'58%'}}/></div></div><div><span>UPI / QR</span><b>₹132,700</b><div><i style={{width:'76%'}}/></div></div><div><span>Card</span><b>₹60,003</b><div><i style={{width:'35%'}}/></div></div></div><div className="breakdown-foot"><span>3 payment methods</span><b>₹362,750</b></div></div></div></>}
function goSalePreview(_set:(s:string)=>void,notify:(s:string)=>void){notify('Your daily sale preview is ready. Use More → Sale Preview to view it.')}
function VendorPage({vendors,search,setSearch,onAdd,onNotify}:{vendors:string[];search:string;setSearch:(s:string)=>void;onAdd:()=>void;onNotify:(s:string)=>void}){const rows=vendors.filter(v=>v.toLowerCase().includes(search.toLowerCase()));return <><div className="page-heading"><div><div className="eyebrow">SUPPLIER DIRECTORY <span className="eyebrow-dot"/> PROCUREMENT</div><h1>Vendors</h1><p>Manage supplier contacts, categories, and purchase history.</p></div><button className="button primary" onClick={onAdd}><Plus size={16}/> Add vendor</button></div><div className="vendor-kpis"><div className="panel"><span className="kpi-icon orange"><Users size={17}/></span><small>Active vendors</small><b>{vendors.length}</b></div><div className="panel"><span className="kpi-icon green"><ShoppingBasket size={17}/></span><small>Purchase orders this month</small><b>42</b></div><div className="panel"><span className="kpi-icon violet"><CircleDollarSign size={17}/></span><small>Outstanding balance</small><b>{fmt(39800)}</b></div></div><div className="panel table-panel"><div className="table-toolbar"><div className="search-box"><Search size={16}/><input placeholder="Search vendor…" value={search} onChange={e=>setSearch(e.target.value)}/></div><span className="table-count">{rows.length} active suppliers</span></div><div className="vendor-grid">{rows.map((v,index)=><article className="vendor-card" key={v}><div className="vendor-card-top"><span className={`vendor-avatar v-${index%6}`}>{v.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><button className="dots" onClick={()=>onNotify(`${v} · Supplier profile`)}><MoreHorizontal size={17}/></button></div><h3>{v}</h3><span className="vendor-category">{['Seafood','Seafood','Meat','Groceries','Vegetables','Spices & pantry','Beverages','Packaging'][index]||'Other'}</span><div className="vendor-meta"><div><small>Contact</small><b>{['Ravi Kumar','Suresh Reddy','Mohan Das','Lakshmi Devi','Ramesh','Annapurna','Metro Sales','Sandeep'][index]||'Supplier contact'}</b></div><div><small>Last purchase</small><b>{['Today','Today','Yesterday','Oct 16','Today','Oct 14','Oct 15','Oct 12'][index]||'No orders yet'}</b></div></div><div className="vendor-card-foot"><span>Monthly purchases</span><b>{fmt([48600,22600,52800,34200,18750,8200,15800,6400][index]||0)}</b></div><button className="vendor-open" onClick={()=>onNotify(`${v}: vendor activity and invoices opened.`)}>View supplier <ArrowRight size={14}/></button></article>)}</div></div></>}
function ReportsPage({report,setReport,selectedDate,onDate,rows,items,activeTab,setActiveTab,notify}:{report:string;setReport:(x:string)=>void;selectedDate:string;onDate:()=>void;rows:SaleRow[];items:Item[];activeTab:string;setActiveTab:(s:string)=>void;notify:(s:string)=>void}){const choices=['Stock Status Report','Stock Movement Report','Sales Report','Expense Report','Daily Cash Report'];const low=items.filter(i=>i.closing<=Math.max(3,i.opening*.25));return <><div className="page-heading"><div><div className="eyebrow">BUSINESS INSIGHTS <span className="eyebrow-dot"/> REPORTS</div><h1>Reports</h1><p>Make better decisions with a clear view of business activity.</p></div><div className="heading-actions"><button className="date-pill" onClick={onDate}><Calendar size={15}/>{selectedDate}<ChevronDown size={14}/></button><button className="button secondary" onClick={()=>notify(`${report} downloaded.`)}><Download size={16}/> Download</button></div></div><div className="report-tabs">{['Stock Status Reports','Stock Movement Reports','Sales Reports','Expense Reports'].map(t=><button key={t} className={t===activeTab?'active':''} onClick={()=>{setActiveTab(t);setReport(t.startsWith('Sales')?'Sales Report':t.startsWith('Expense')?'Expense Report':t.startsWith('Stock Movement')?'Stock Movement Report':'Stock Status Report')}}>{t}</button>)}</div><div className="report-layout"><aside className="panel report-picker"><b>REPORT TYPE</b>{choices.map(c=><button key={c} className={report===c?'active':''} onClick={()=>setReport(c)}>{c}<ChevronRight size={14}/></button>)}</aside><div className="report-content"><div className="panel report-head"><div><span className="report-icon"><FileChartColumn size={18}/></span><div><h2>{report}</h2><p>Reporting period · October 2026</p></div></div><span className="status-pill paid"><Check size={12}/> Up to date</span></div><div className="report-metrics"><div><small>{report.includes('Stock')?'Items in stock':'Gross sales'}</small><b>{report.includes('Stock')?items.length:fmt(rows.filter(r=>r.kind==='Sale').reduce((a,x)=>a+x.amount,0)||362750)}</b><em>For selected period</em></div><div><small>{report.includes('Stock')?'Low stock items':'Total transactions'}</small><b>{report.includes('Stock')?low.length:rows.length}</b><em>{report.includes('Stock')?'Requires attention':'Recorded in ledger'}</em></div><div><small>Net change</small><b className="positive">+8.2%</b><em>Compared to last period</em></div></div><div className="panel report-chart-panel"><div className="panel-head"><div><h2>{report.includes('Stock')?'Inventory by category':'Sales & expenses'}</h2><p>October 1 – 17, 2026</p></div><button className="select-button">This month <ChevronDown size={14}/></button></div><div className="report-chart">{(report.includes('Stock')?['Seafood','Meat','Groceries','Vegetables','Spices','Other']:['Oct 1','Oct 3','Oct 5','Oct 7','Oct 9','Oct 11','Oct 13','Oct 15','Oct 17']).map((x,i)=><div key={x}><span className="report-bar" style={{height:`${[68,45,88,52,38,59,73,92,63][i]}%`}}/><small>{x}</small></div>)}</div></div><div className="panel report-table"><div className="panel-head"><div><h2>Report details</h2><p>{report.includes('Stock')?`${items.length} items included`:`${rows.length} ledger entries included`}</p></div><button className="text-link" onClick={()=>notify(`${report} exported.`)}>Export data <ArrowRight size={14}/></button></div><div className="table-scroll">{report.includes('Stock')?<table className="data-table"><thead><tr><th>Product</th><th>Category</th><th>Closing stock</th><th>Value</th><th>Status</th></tr></thead><tbody>{items.slice(0,6).map(i=><tr key={i.code}><td><b>{i.name}</b></td><td>{i.category}</td><td>{i.closing} {i.unit}</td><td>{fmt(i.closing*i.price)}</td><td><span className={`status-pill ${i.closing<=5?'pending':'paid'}`}>{i.closing<=5?'Reorder':'In stock'}</span></td></tr>)}</tbody></table>:<table className="data-table"><thead><tr><th>Date</th><th>Description</th><th>Type</th><th>Amount</th></tr></thead><tbody>{rows.slice(0,6).map((r,i)=><tr key={i}><td>{r.date}</td><td>{r.name}</td><td>{r.kind}</td><td>{fmt(r.amount)}</td></tr>)}</tbody></table>}</div></div></div></div><div className="report-quick"><div><h3>Quick access</h3><p>Frequently used business summaries</p></div>{['Stock Status Report','Stock Movement Report','Sales Report','Expense Report'].map(r=><button key={r} onClick={()=>setReport(r)}><FileChartColumn size={15}/>{r}<ArrowRight size={14}/></button>)}</div></>}
function MorePage({go}:{go:(p:Page)=>void}){const items:{name:Page;description:string;icon:LucideIcon;color:string}[]=[{name:'Sale Preview',description:'Review and share today’s sale summary',icon:Eye,color:'orange'},{name:'Set Sale Priority',description:'Choose products to highlight in sales',icon:SlidersHorizontal,color:'violet'},{name:'Set Vendor Priority',description:'Set your preferred purchasing suppliers',icon:Truck,color:'blue'},{name:'Estimation Sheet',description:'Prepare ingredient and cost estimates',icon:ClipboardList,color:'green'},{name:'Reports',description:'Sales, stock, and expense reports',icon:BarChart3,color:'amber'},{name:'Schedule',description:'Plan upcoming stock and purchase checks',icon:CalendarDays,color:'pink'},{name:'Settings',description:'Business details and app preferences',icon:Settings,color:'gray'}];return <><div className="page-heading"><div><div className="eyebrow">TOOLS &amp; PREFERENCES</div><h1>More</h1><p>Everything you need to manage your restaurant.</p></div></div><div className="more-layout"><div className="panel more-menu">{items.map(({name,description,icon:Icon,color})=><button key={name} onClick={()=>go(name)}><span className={`more-icon ${color}`}><Icon size={17}/></span><span><b>{name}</b><small>{description}</small></span><ChevronRight size={17}/></button>)}</div><div className="panel help-card"><span className="help-graphic"><CookingPot size={31}/></span><h2>Your restaurant, in control.</h2><p>Get help with your stock sheet, daily ledger, and reporting tools.</p><button className="text-link" onClick={()=>go('Settings')}>Open preferences <ArrowRight size={14}/></button><div className="help-version">Prawns Ledger <span>·</span> Version 1.0.0</div></div></div><button className="logout-button" onClick={()=>go('Home')}><LogOut size={15}/> Sign out</button></>}
function SalePreview({sales,selectedDate,setSelectedDate,go}:{sales:SaleRow[];selectedDate:string;setSelectedDate:(s:string)=>void;go:(p:Page)=>void}){const day=sales.filter(s=>s.date===selectedDate);return <><div className="page-heading"><div><div className="eyebrow">DAILY SUMMARY <span className="eyebrow-dot"/> SALE PREVIEW</div><h1>Sale preview</h1><p>Review the daily summary before sharing with your team.</p></div><div className="heading-actions"><button className="date-pill" onClick={()=>{const d=prompt('Choose a date (YYYY-MM-DD)',selectedDate);if(d)setSelectedDate(d)}}><Calendar size={15}/>{selectedDate}<ChevronDown size={14}/></button><button className="button primary" onClick={()=>window.print()}><Download size={16}/> Print preview</button></div></div><div className="preview-card"><div className="preview-brand"><span className="brand-mark"><CookingPot size={19}/></span><div><b>Nirooi Adelli Pochamma Wines Nirmal</b><small>Restaurant daily sales summary</small></div><span className="preview-date">{new Date(`${selectedDate}T00:00:00`).toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</span></div><div className="preview-stats"><div><small>Counter cash</small><b>{fmt(170047)}</b></div><div><small>Invoice amount</small><b>{fmt(511310)}</b></div><div><small>Sale amount</small><b>{fmt(362750)}</b></div><div><small>Expenditure</small><b>{fmt(18745)}</b></div></div><h3>Transaction details</h3><TransactionList rows={day.length?day:sales.slice(0,4)}/><button className="button secondary" onClick={()=>go('Home')}><ArrowLeft size={15}/> Return to dashboard</button></div></>}
function PriorityPage({title,icon:Icon,names,notify}:{title:string;icon:LucideIcon;names:string[];notify:(s:string)=>void}){const [order,setOrder]=useState(names);const [saved,setSaved]=useState(false);return <><div className="page-heading"><div><div className="eyebrow">PREFERENCES <span className="eyebrow-dot"/> PRIORITY MANAGEMENT</div><h1>{title}</h1><p>Drag items into the order you want your team to prioritize.</p></div><button className="button primary" onClick={()=>{setSaved(true);notify(`${title} order saved.`)}}><Check size={16}/> Save priorities</button></div><div className="panel priority-panel"><div className="panel-head"><div><h2><Icon size={18}/> Priority order</h2><p>Items at the top will appear first in your daily workflow.</p></div><span className="status-pill paid">{saved?'Saved':'Draft'}</span></div>{order.map((n,i)=><div className="priority-row" key={n}><span className="priority-num">{String(i+1).padStart(2,'0')}</span><span className="drag-handle">⠿</span><span className="priority-item"><b>{n}</b><small>{title==='Vendor priority'?'Preferred supplier':'Frequently sold product'}</small></span><button className="priority-shift" disabled={i===0} onClick={()=>setOrder(order.map((x,j)=>j===i?order[i-1]:j===i-1?order[i]:x))}><ChevronUpIcon/></button><button className="priority-shift" disabled={i===order.length-1} onClick={()=>setOrder(order.map((x,j)=>j===i?order[i+1]:j===i+1?order[i]:x))}><ChevronDown size={16}/></button></div>)}<p className="table-note">Priority settings apply to the current workspace and can be changed any time.</p></div></>}
function ChevronUpIcon(){return <ChevronLeft size={16} style={{transform:'rotate(90deg)'}}/>}
function EstimatePage({items,notify}:{items:Item[];notify:(s:string)=>void}){const [quantities,setQuantities]=useState<Record<string,number>>({});const total=items.reduce((s,i)=>s+(quantities[i.code]??i.sale)*i.price,0);return <><div className="page-heading"><div><div className="eyebrow">PLANNING TOOLS <span className="eyebrow-dot"/> COST ESTIMATION</div><h1>Estimation sheet</h1><p>Estimate ingredient requirements and purchase costs before the next shift.</p></div><button className="button primary" onClick={()=>notify(`Estimate saved · projected cost ${fmt(total)}.`)}><Check size={16}/> Save estimate</button></div><div className="estimate-summary"><div><small>Estimated purchase total</small><b>{fmt(total)}</b><span>Based on your current vendor cost</span></div><div><small>Items in estimate</small><b>{items.length}</b><span>Adjust quantities in the table</span></div></div><div className="panel table-panel"><div className="panel-head estimate-head"><div><h2>Purchase estimate</h2><p>Suggested quantities are based on recent usage.</p></div><button className="button secondary" onClick={()=>notify('Estimate exported as CSV.')}><Download size={15}/> Export</button></div><div className="table-scroll"><table className="data-table"><thead><tr><th>Product</th><th>Current stock</th><th>Suggested qty</th><th>Cost / unit</th><th>Estimated cost</th></tr></thead><tbody>{items.slice(0,10).map(i=>{const q=quantities[i.code]??Math.max(i.sale-i.closing,0);return <tr key={i.code}><td><b>{i.name}</b><small className="table-secondary">{i.vendor}</small></td><td>{i.closing} {i.unit}</td><td><input className="quantity-input" type="number" min="0" value={q} onChange={e=>setQuantities({...quantities,[i.code]:Number(e.target.value)})}/></td><td>{fmt(i.price)}</td><td className="money-strong">{fmt(q*i.price)}</td></tr>})}</tbody></table></div></div></>}
function SchedulePage({notify}:{notify:(s:string)=>void}){const [events,setEvents]=useState([{date:'2026-10-18',name:'Weekly seafood order',type:'Purchase',color:'orange'},{date:'2026-10-20',name:'Stock count · kitchen',type:'Inventory',color:'green'},{date:'2026-10-24',name:'Vendor payment · Coastal Catch',type:'Payment',color:'violet'},{date:'2026-10-26',name:'Monthly stock review',type:'Review',color:'blue'}]);return <><div className="page-heading"><div><div className="eyebrow">PLAN AHEAD <span className="eyebrow-dot"/> OPERATIONS</div><h1>Schedule</h1><p>Stay ahead of orders, stock counts, and supplier payments.</p></div><button className="button primary" onClick={()=>{const name=prompt('What would you like to schedule?');if(name){setEvents([...events,{date:today(),name,type:'Reminder',color:'orange'}]);notify('Reminder added to your schedule.')}}}><Plus size={16}/> Add reminder</button></div><div className="schedule-layout"><div className="panel calendar-panel"><div className="panel-head"><div><h2>October 2026</h2><p>Upcoming operational tasks</p></div><div className="calendar-arrows"><button onClick={()=>notify('Showing September 2026.')}><ChevronLeft size={16}/></button><button onClick={()=>notify('Showing November 2026.')}><ChevronRight size={16}/></button></div></div><div className="calendar-grid">{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=><small key={x}>{x}</small>)}{Array.from({length:35},(_,i)=>{const d=i-2;return <button key={i} className={`${d===17?'today':''} ${d<1||d>31?'muted-date':''}`}>{d<1?30+d:d>31?d-31:d}{events.some(e=>Number(e.date.slice(-2))===d)&&<i/>}</button>})}</div></div><div className="panel upcoming-panel"><div className="panel-head"><div><h2>Upcoming</h2><p>Next operational reminders</p></div><span className="count-badge">{events.length} tasks</span></div>{events.map(e=><div className="event-row" key={e.name}><span className={`event-date ${e.color}`}><b>{e.date.slice(-2)}</b><small>OCT</small></span><span className="event-info"><b>{e.name}</b><small>{e.type} · {e.date}</small></span><button className="dots" onClick={()=>{setEvents(events.filter(x=>x.name!==e.name));notify('Reminder removed.')}}><MoreHorizontal size={16}/></button></div>)}</div></div></>}
function SettingsPage({notify,items,sales,invoices}:{notify:(s:string)=>void;items:Item[];sales:SaleRow[];invoices:Invoice[]}){const [toggles,setToggles]=useState({invoice:true,alerts:true,compact:false});return <><div className="page-heading"><div><div className="eyebrow">PREFERENCES <span className="eyebrow-dot"/> WORKSPACE</div><h1>Settings</h1><p>Configure your restaurant profile and workspace preferences.</p></div><button className="button primary" onClick={()=>notify('Settings saved.') }><Check size={16}/> Save changes</button></div><div className="settings-layout"><div className="panel settings-card"><div className="settings-title"><span className="settings-icon"><Store size={18}/></span><div><h2>Business details</h2><p>Information shown on your ledger and daily reports</p></div></div><div className="form-grid"><label>Business name<input defaultValue="Nirooi Adelli Pochamma Wines Nirmal"/></label><label>Business type<select defaultValue="Restaurant"><option>Restaurant</option><option>Cafe</option><option>Retail</option></select></label><label>Location<input defaultValue="Nirmal, Telangana"/></label><label>Currency<select defaultValue="INR · Indian Rupee"><option>INR · Indian Rupee</option><option>USD · US Dollar</option></select></label></div></div><div className="panel settings-card"><div className="settings-title"><span className="settings-icon"><Bell size={18}/></span><div><h2>Preferences</h2><p>Choose how the app works for your team</p></div></div>{[['invoice','Invoice upload reminders','Get a nudge when a supplier invoice needs review.'],['alerts','Low stock alerts','Show a dashboard alert when an item needs reorder.'],['compact','Compact tables','Use denser row spacing for data tables.']].map(([key,name,desc])=><div className="setting-row" key={key}><span><b>{name}</b><small>{desc}</small></span><button className={`switch ${toggles[key as keyof typeof toggles]?'on':''}`} onClick={()=>setToggles({...toggles,[key]:!toggles[key as keyof typeof toggles]})}><i/></button></div>)}</div><div className="panel settings-card"><div className="settings-title"><span className="settings-icon"><CloudUpload size={18}/></span><div><h2>Your data</h2><p>Data is saved locally in this browser on this device.</p></div></div><div className="data-actions"><button className="button secondary" onClick={()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({items,sales,invoices},null,2)],{type:'application/json'}));a.download='prawns-ledger-backup.json';a.click();notify('Backup file downloaded.')}}><Download size={15}/> Export backup</button><button className="button secondary" onClick={()=>notify('Local data is stored in this browser and will remain available on this device.')}><CloudUpload size={15}/> Data storage info</button></div></div></div></>}
export default App;
